            "Каждый шаг работал со своим слоем. High Tension — это про топшит: по официальному определению, технология добавляет натяжение самой молекуле резины за счёт нанесения специальных веществ. Проще говоря, поверхность заранее «взводят как пружину», и она реагирует на мяч активнее обычной резины.",
